var t=[{title:`Was eine aerobe Basis ist`,text:`Aerobes Training stützt sich bei anhaltender Aktivität hauptsächlich auf Sauerstoff, um Energie zu erzeugen. Regelmäßige leichte oder moderate aerobe Arbeit kann verbessern, wie Herz, Lunge und Muskeln arbeiten. Du musst dich nicht erschöpfen, um dich zu verbessern: Gleichmäßige Arbeit, die du Woche für Woche wiederholen kannst, zählt mehr als eine dramatische Einheit.`},{title:`Leichte Intensität`,text:`„Zone 2“ wird oft für ein Gesprächstempo verwendet, aber Zonen aus einem Labortest und Zonen von einem Wearable stimmen nicht immer überein. Der Sprechtest ist ein praktischer Anhaltspunkt: Bei moderatem Tempo kannst du sprechen, aber nicht singen. Auch langsamere, bequeme Belastungen helfen, besonders wenn du mit sehr wenig Aktivität beginnst.`},{title:`Minuten stetig steigern`,text:`Als Anfänger könntest du mit drei 15-Minuten-Spaziergängen pro Woche beginnen und Minuten hinzufügen, wenn sie leichter werden. Arbeite auf Ziele der öffentlichen Gesundheit wie 150 Minuten moderate aerobe Aktivität pro Woche hin, in einem Tempo, das zu deiner Bereitschaft und deinem Zeitplan passt. Lange Einheiten sind nicht nötig, wenn du kürzere regelmäßig wiederholen kannst. Gehen, Radfahren und gleichmäßige Zirkel mit geringer Belastung zählen alle, wähle also, was deine Ausrüstung und dein Platz erlauben, und erreiche eine Wochenmenge, die du durchhältst, bevor du HIIT hinzufügst.`},{title:`Verfolge die Veränderungen, die zählen`,text:`Achte darauf, ob derselbe Spaziergang dich weniger außer Atem lässt, ob du bei Gesprächstempo mehr Strecke schaffst oder ob es sich leichter anfühlt. Veränderungen können sich über mehrere Wochen zeigen, und wie schnell, hängt von deiner Ausgangsfitness, deinem Schlaf, Gelände, Wetter und deiner Regelmäßigkeit ab. Zeit und wie anstrengend es sich anfühlte, sagen dir mehr als geschätzte Herzfrequenzzonen, die ungenau sein können.`}];var i=[{label:`CDC: Empfehlungen zur körperlichen Aktivität für Erwachsene`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`},{label:`CDC: Intensität der Aktivität messen und Sprechtest`,url:`https://www.cdc.gov/physicalactivity/basics/measuring/index.html`},{label:`CDC: Training bei Hitze`,url:`https://www.cdc.gov/heat-health/risk-factors/heat-and-athletes.html`}];var r={sections:t,sources:i};export{r as default,t as sections,i as sources};